import json
def flat(d,p=''):
    o={}
    for k,v in d.items():
        q=f'{p}.{k}' if p else k
        if isinstance(v,dict): o.update(flat(v,q))
        else: o[q]=v
    return o
b=json.load(open('crustify/tmp/ffimap-base.json')); t=json.load(open('crustify/tmp/ffimap-tree.json'))
print({k:b[k] for k in b if k!='counts'}); print({k:t[k] for k in t if k!='counts'})
fb,ft=flat(b['counts']),flat(t['counts'])
for k in sorted(set(fb)|set(ft)):
    if fb.get(k)!=ft.get(k): print(k,fb.get(k),'->',ft.get(k))
s=json.load(open('crustify/tmp/ffimap-sites.json'))['sites']
for k,v in s.items():
    hits=[x for x in v if 'cc_compat' in json.dumps(x) or 'equiv/src/util/cc' in json.dumps(x)]
    print(k,len(v),'in changeset:',hits)
EOF

